from collections import Counter


def transform(grid):
    """Fill each background cell between matching non-background neighbors horizontally."""
    if not grid:
        return []
    width = len(grid[0])
    if any(len(row) != width for row in grid):
        raise ValueError("grid must be rectangular")
    background = Counter(cell for row in grid for cell in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c in range(1, width - 1):
            if row[c] == background and row[c - 1] == row[c + 1] != background:
                out[r][c] = 2
    return out

